    std::vector<int> maxes;
    for (int i = 0; i < static_cast<int>(nums.size()); i++) {
        while (!window.empty() && nums[window.back()] <= nums[i]) {
            window.pop_back();
        }
        window.push_back(i);
        if (window.front() <= i - k) {
            window.pop_front();
        }
        if (i >= k - 1) {
            maxes.push_back(nums[window.front()]);
        }
    }
    return maxes;
}

