import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function maxSlidingWindow(nums: number[], k: number): number[] {
  const deque: number[] = []; // indexes, their numbers getting smaller from front to back
  let head = 0; // the front of the deque is deque[head]
  // The number at the index held in one slot of the deque.
  const numAt = (slot: number): number => nums[deque[slot] ?? -1] ?? -Infinity;
  const maxes: number[] = [];
  for (const [i, num] of nums.entries()) {
    while (deque.length > head && numAt(deque.length - 1) <= num) {
      deque.pop();
    }
    deque.push(i);
    if ((deque[head] ?? i) <= i - k) {
      head++;
    }
    if (i >= k - 1) {
      maxes.push(numAt(head));
    }
  }
  return maxes;
}

const [n = 0, k = 1, ...nums] = input.trim().split(/\s+/).map(Number);
console.log(maxSlidingWindow(nums.slice(0, n), k).join(" "));
